-- READ-ONLY source-only timestamp counts by UTC quarter, interval and units; years stop at 2020.
SELECT YEAR(FROM_UNIXTIME(a.dateTime)) utc_year,QUARTER(FROM_UNIXTIME(a.dateTime)) utc_quarter,a.interval interval_min,a.usUnits,COUNT(DISTINCT a.dateTime) timestamps FROM (SELECT a.dateTime,a.interval,a.usUnits FROM old_weewx.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL UNION SELECT a.dateTime,a.interval,a.usUnits FROM weewx_WH1080.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL) a GROUP BY utc_year,utc_quarter,interval_min,usUnits ORDER BY utc_year,utc_quarter,interval_min,usUnits;
